         final long maxOrd;
         if (upperValue == null) {
           maxOrd = values.getValueCount() - 1;
         } else {
           final long ord = values.lookupTerm(upperValue);
           if (ord < 0) {
             maxOrd = -2 - ord;
           } else if (upperInclusive) {
             maxOrd = ord;
           } else {
             maxOrd = ord - 1;
           }
         }

         if (minOrd > maxOrd) {
           return null;
         }

